    {
        _connectionString = connectionString;
        _query = query;
    }

    public IConfigurationProvider Build(IConfigurationBuilder builder)
    {
        return new SqlConfigurationProvider(_connectionString, _query);
    }
}
```
In this example, the `SqlConfigurationSource` constructor takes a connection string and a SQL query as parameters. The `Build` method creates an instance of the `SqlConfigurationProvider` and returns it.

