  new Image(),
  new Image()
];
tileImages[0].src = 'path/to/tile0.png';
tileImages[1].src = 'path/to/tile1.png';

// Wait for all tile images to load before drawing
Promise.all(tileImages.map(img => new Promise((resolve, reject) => {
  img.onload = resolve;
  img.onerror = reject;
})))
.then(() => {
  // Draw the tile map onto the canvas
  for (let row = 0; row < tileMap.length; row++) {
    for (let col = 0; col < tileMap[row].length; col++) {
      const tileIndex = tileMap[row][col];
      const tileImage = tileImages[tileIndex];
      const x = col * tileSize;
      const y = row * tileSize;
      ctx.drawImage(tileImage, x, y, tileSize, tileSize);
    }
  }
});
